SELECT "t4"."line_id", "t4"."qty_ok", "t4"."qty_bad", "t4"."last_received", 'complete' AS "route", 'receipts' AS "context"
FROM (SELECT "t1"."line_id", COALESCE(SUM(CASE WHEN "return_receipt"."condition" = 'ok' THEN "return_receipt"."quantity" ELSE 0 END), 0) AS "qty_ok", COALESCE(SUM(CASE WHEN "return_receipt"."condition" <> 'ok' THEN "return_receipt"."quantity" ELSE 0 END), 0) AS "qty_bad", MAX("return_receipt"."received_date") AS "last_received"
        FROM (SELECT "t"."line_id", "t"."request_number", "t"."item", "t"."quantity", "t"."way", "t"."customer0" AS "customer", "obligation"."id" AS "obligation_id", "obligation"."due", "obligation"."state" AS "obligation_state"
                FROM (SELECT "return_request_line"."line_id", "return_request_line"."request_number", "return_request_line"."line_no", "return_request_line"."item", "return_request_line"."quantity", "return_request_line"."unit_price", "return_request_line"."reason", "return_request_line"."requested_resolution", "return_request_line"."requested_variant", "return_request_line"."state", "return_request_line"."way", "return_request_line"."customer", "return_request"."customer" AS "customer0", "return_request"."order_number", "return_request"."channel", "return_request"."requested_date", "return_request"."state" AS "state0"
                        FROM "return_request_line"
                            INNER JOIN "return_request" ON "return_request_line"."request_number" = "return_request"."request_number") AS "t"
                    INNER JOIN "obligation" ON "obligation"."entity" = 'return_request_line' AND "obligation"."key" = CAST("t"."line_id" AS VARCHAR) AND "obligation"."kind" = 'inbound' AND "obligation"."state" IN ('open', 'overdue', 'reopened')
                WHERE "t"."state" = 'awaiting_goods') AS "t1"
            LEFT JOIN "return_receipt" ON "t1"."line_id" = "return_receipt"."line_id"
        GROUP BY "t1"."line_id") AS "t4"
    INNER JOIN (SELECT "line_id"
        FROM (SELECT "t28"."line_id", "t28"."request_number", "t28"."item", "t28"."quantity", "t28"."way", "t28"."customer", "t28"."obligation_id", "t28"."due", "t28"."obligation_state", "t28"."qty_ok", "t28"."qty_bad", "t28"."last_received", "t28"."days_open", "t32"."reminders", CASE WHEN "t28"."qty_ok" >= "t28"."quantity" THEN 'complete' WHEN "t28"."qty_bad" > 0 OR "t28"."qty_ok" > 0 AND "t28"."qty_ok" < "t28"."quantity" THEN 'damaged' WHEN "t28"."days_open" > :inbound_close THEN 'expired' WHEN "t28"."days_open" > :inbound_reminder AND "t32"."reminders" = 0 THEN 'remind' ELSE NULL END AS "route"
                FROM (SELECT "t14"."line_id", "t14"."request_number", "t14"."item", "t14"."quantity", "t14"."way", "t14"."customer", "t14"."obligation_id", "t14"."due", "t14"."obligation_state", "t14"."qty_ok", "t14"."qty_bad", "t14"."last_received", "t27"."days_open"
                        FROM (SELECT "t7"."line_id", "t7"."request_number", "t7"."item", "t7"."quantity", "t7"."way", "t7"."customer", "t7"."obligation_id", "t7"."due", "t7"."obligation_state", "t13"."qty_ok", "t13"."qty_bad", "t13"."last_received"
                                FROM (SELECT "t5"."line_id", "t5"."request_number", "t5"."item", "t5"."quantity", "t5"."way", "t5"."customer0" AS "customer", "obligation0"."id" AS "obligation_id", "obligation0"."due", "obligation0"."state" AS "obligation_state"
                                        FROM (SELECT "return_request_line0"."line_id", "return_request_line0"."request_number", "return_request_line0"."line_no", "return_request_line0"."item", "return_request_line0"."quantity", "return_request_line0"."unit_price", "return_request_line0"."reason", "return_request_line0"."requested_resolution", "return_request_line0"."requested_variant", "return_request_line0"."state", "return_request_line0"."way", "return_request_line0"."customer", "return_request0"."customer" AS "customer0", "return_request0"."order_number", "return_request0"."channel", "return_request0"."requested_date", "return_request0"."state" AS "state0"
                                                FROM "return_request_line" AS "return_request_line0"
                                                    INNER JOIN "return_request" AS "return_request0" ON "return_request_line0"."request_number" = "return_request0"."request_number") AS "t5"
                                            INNER JOIN "obligation" AS "obligation0" ON "obligation0"."entity" = 'return_request_line' AND "obligation0"."key" = CAST("t5"."line_id" AS VARCHAR) AND "obligation0"."kind" = 'inbound' AND "obligation0"."state" IN ('open', 'overdue', 'reopened')
                                        WHERE "t5"."state" = 'awaiting_goods') AS "t7"
                                    LEFT JOIN (SELECT "t10"."line_id", COALESCE(SUM(CASE WHEN "return_receipt0"."condition" = 'ok' THEN "return_receipt0"."quantity" ELSE 0 END), 0) AS "qty_ok", COALESCE(SUM(CASE WHEN "return_receipt0"."condition" <> 'ok' THEN "return_receipt0"."quantity" ELSE 0 END), 0) AS "qty_bad", MAX("return_receipt0"."received_date") AS "last_received"
                                        FROM (SELECT "t8"."line_id", "t8"."request_number", "t8"."item", "t8"."quantity", "t8"."way", "t8"."customer0" AS "customer", "obligation1"."id" AS "obligation_id", "obligation1"."due", "obligation1"."state" AS "obligation_state"
                                                FROM (SELECT "return_request_line1"."line_id", "return_request_line1"."request_number", "return_request_line1"."line_no", "return_request_line1"."item", "return_request_line1"."quantity", "return_request_line1"."unit_price", "return_request_line1"."reason", "return_request_line1"."requested_resolution", "return_request_line1"."requested_variant", "return_request_line1"."state", "return_request_line1"."way", "return_request_line1"."customer", "return_request1"."customer" AS "customer0", "return_request1"."order_number", "return_request1"."channel", "return_request1"."requested_date", "return_request1"."state" AS "state0"
                                                        FROM "return_request_line" AS "return_request_line1"
                                                            INNER JOIN "return_request" AS "return_request1" ON "return_request_line1"."request_number" = "return_request1"."request_number") AS "t8"
                                                    INNER JOIN "obligation" AS "obligation1" ON "obligation1"."entity" = 'return_request_line' AND "obligation1"."key" = CAST("t8"."line_id" AS VARCHAR) AND "obligation1"."kind" = 'inbound' AND "obligation1"."state" IN ('open', 'overdue', 'reopened')
                                                WHERE "t8"."state" = 'awaiting_goods') AS "t10"
                                            LEFT JOIN "return_receipt" AS "return_receipt0" ON "t10"."line_id" = "return_receipt0"."line_id"
                                        GROUP BY "t10"."line_id") AS "t13" ON "t7"."line_id" = "t13"."line_id") AS "t14"
                            LEFT JOIN (SELECT "t18"."line_id", CASE WHEN "t18"."_ttrp_a_n15_0" IS NULL THEN NULL ELSE COALESCE("t26"."_ttrp_n_n15_0", 0) END AS "days_open"
                                FROM (SELECT "t17"."line_id", "t17"."request_number", "t17"."item", "t17"."quantity", "t17"."way", "t17"."customer", "t17"."obligation_id", "t17"."due", "t17"."obligation_state", "obligation3"."recipe", "obligation3"."run", "obligation3"."entity", "obligation3"."key", "obligation3"."kind", "obligation3"."due" AS "due0", "obligation3"."state", "obligation3"."fulfilled_by", "obligation3"."fulfilled_at", "obligation3"."created_at", "obligation3"."created_at" AS "_ttrp_a_n15_0"
                                        FROM (SELECT "t15"."line_id", "t15"."request_number", "t15"."item", "t15"."quantity", "t15"."way", "t15"."customer0" AS "customer", "obligation2"."id" AS "obligation_id", "obligation2"."due", "obligation2"."state" AS "obligation_state"
                                                FROM (SELECT "return_request_line2"."line_id", "return_request_line2"."request_number", "return_request_line2"."line_no", "return_request_line2"."item", "return_request_line2"."quantity", "return_request_line2"."unit_price", "return_request_line2"."reason", "return_request_line2"."requested_resolution", "return_request_line2"."requested_variant", "return_request_line2"."state", "return_request_line2"."way", "return_request_line2"."customer", "return_request2"."customer" AS "customer0", "return_request2"."order_number", "return_request2"."channel", "return_request2"."requested_date", "return_request2"."state" AS "state0"
                                                        FROM "return_request_line" AS "return_request_line2"
                                                            INNER JOIN "return_request" AS "return_request2" ON "return_request_line2"."request_number" = "return_request2"."request_number") AS "t15"
                                                    INNER JOIN "obligation" AS "obligation2" ON "obligation2"."entity" = 'return_request_line' AND "obligation2"."key" = CAST("t15"."line_id" AS VARCHAR) AND "obligation2"."kind" = 'inbound' AND "obligation2"."state" IN ('open', 'overdue', 'reopened')
                                                WHERE "t15"."state" = 'awaiting_goods') AS "t17"
                                            INNER JOIN "obligation" AS "obligation3" ON "t17"."obligation_id" = "obligation3"."id") AS "t18"
                                    LEFT JOIN (SELECT "t23"."_ttrp_a_n15_0" AS "_ttrp_k_n15_0__ttrp_a_n15_0", COUNT("t24"."_ttrp_d_n15_0") AS "_ttrp_n_n15_0"
                                        FROM (SELECT "obligation5"."created_at" AS "_ttrp_a_n15_0"
                                                FROM (SELECT "t19"."line_id", "t19"."request_number", "t19"."item", "t19"."quantity", "t19"."way", "t19"."customer0" AS "customer", "obligation4"."id" AS "obligation_id", "obligation4"."due", "obligation4"."state" AS "obligation_state"
                                                        FROM (SELECT "return_request_line3"."line_id", "return_request_line3"."request_number", "return_request_line3"."line_no", "return_request_line3"."item", "return_request_line3"."quantity", "return_request_line3"."unit_price", "return_request_line3"."reason", "return_request_line3"."requested_resolution", "return_request_line3"."requested_variant", "return_request_line3"."state", "return_request_line3"."way", "return_request_line3"."customer", "return_request3"."customer" AS "customer0", "return_request3"."order_number", "return_request3"."channel", "return_request3"."requested_date", "return_request3"."state" AS "state0"
                                                                FROM "return_request_line" AS "return_request_line3"
                                                                    INNER JOIN "return_request" AS "return_request3" ON "return_request_line3"."request_number" = "return_request3"."request_number") AS "t19"
                                                            INNER JOIN "obligation" AS "obligation4" ON "obligation4"."entity" = 'return_request_line' AND "obligation4"."key" = CAST("t19"."line_id" AS VARCHAR) AND "obligation4"."kind" = 'inbound' AND "obligation4"."state" IN ('open', 'overdue', 'reopened')
                                                        WHERE "t19"."state" = 'awaiting_goods') AS "t21"
                                                    INNER JOIN "obligation" AS "obligation5" ON "t21"."obligation_id" = "obligation5"."id"
                                                GROUP BY "obligation5"."created_at") AS "t23"
                                            INNER JOIN (SELECT "cal_date" AS "_ttrp_d_n15_0"
                                                FROM "date_dim") AS "t24" ON "t23"."_ttrp_a_n15_0" < "t24"."_ttrp_d_n15_0" AND "t24"."_ttrp_d_n15_0" <= :as_of
                                        GROUP BY "t23"."_ttrp_a_n15_0") AS "t26" ON "t18"."_ttrp_a_n15_0" = "t26"."_ttrp_k_n15_0__ttrp_a_n15_0") AS "t27" ON "t14"."line_id" = "t27"."line_id") AS "t28"
                    LEFT JOIN (SELECT "t31"."line_id", COUNT("monitor_inbound_verdict"."run") AS "reminders"
                        FROM (SELECT "t29"."line_id", "t29"."request_number", "t29"."item", "t29"."quantity", "t29"."way", "t29"."customer0" AS "customer", "obligation6"."id" AS "obligation_id", "obligation6"."due", "obligation6"."state" AS "obligation_state"
                                FROM (SELECT "return_request_line4"."line_id", "return_request_line4"."request_number", "return_request_line4"."line_no", "return_request_line4"."item", "return_request_line4"."quantity", "return_request_line4"."unit_price", "return_request_line4"."reason", "return_request_line4"."requested_resolution", "return_request_line4"."requested_variant", "return_request_line4"."state", "return_request_line4"."way", "return_request_line4"."customer", "return_request4"."customer" AS "customer0", "return_request4"."order_number", "return_request4"."channel", "return_request4"."requested_date", "return_request4"."state" AS "state0"
                                        FROM "return_request_line" AS "return_request_line4"
                                            INNER JOIN "return_request" AS "return_request4" ON "return_request_line4"."request_number" = "return_request4"."request_number") AS "t29"
                                    INNER JOIN "obligation" AS "obligation6" ON "obligation6"."entity" = 'return_request_line' AND "obligation6"."key" = CAST("t29"."line_id" AS VARCHAR) AND "obligation6"."kind" = 'inbound' AND "obligation6"."state" IN ('open', 'overdue', 'reopened')
                                WHERE "t29"."state" = 'awaiting_goods') AS "t31"
                            LEFT JOIN "monitor_inbound_verdict" ON "t31"."line_id" = "monitor_inbound_verdict"."line_id" AND "monitor_inbound_verdict"."route" = 'remind'
                        GROUP BY "t31"."line_id") AS "t32" ON "t28"."line_id" = "t32"."line_id") AS "t33"
        WHERE "t33"."route" = 'complete'
        GROUP BY "line_id") AS "t36" ON "t4"."line_id" = "t36"."line_id"
